 const rowDrafts=useRef<Record<string,Record<string,unknown>>>({});const [connectionNotes,setConnectionNotes]=useState('');const connectionDrafts=useRef<Record<string,Record<string,unknown>>>({});const configuredType=useRef<string|null>(null);
