 function saveChanges(){if(formHasDraft){message.warning('请先按 Enter 确认字段内容');return}if(editing){message.warning('请先按 Enter 确认单元格内容');return}if(document.querySelector('.record-form-input[aria-invalid="true"]')){message.warning('请先修正字段中的无效值');return}const next={...tables};for(const [name,draft] of Object.entries(schemaDrafts)){if(!tables[name]||!schemaDraftChanged(tables[name],draft))continue;const compiled=compileSchemaDraft(tables[name],draft);if(!compiled.ok){message.error(`${name}：${compiled.error}`);openTable(name);setView('结构');return}next[name]=compiled.table}for(const source of Object.values(next)){const checked=compileSchemaDraft(source,createSchemaDraft(source));if(!checked.ok){message.error(`${source.name}：${checked.error}`);return}}try{localStorage.setItem('db-studio-tables-v1',JSON.stringify(next))}catch{message.error('当前浏览器无法保存更改，请检查存储空间');return}if(selectedCell){const renamed=schemaDrafts[selectedCell.table]?.find(field=>field.sourceName===selectedCell.col);if(renamed)setSelectedCell({...selectedCell,col:renamed.name.trim()})}setTables(next);committed.current=structuredClone(next);setSchemaDrafts({});originalRowIds.current.clear();setPending(false);setEditRevision(v=>v+1);message.success('更改已应用到当前浏览器')}
