 function addRow(){rowForm.validateFields().then(values=>{if(!table)return;const id=Math.max(0,...table.rows.map(r=>Number(r.id)))+1;const row:Row={};for(const c of table.columns){const v=c.name==='id'?id:values[c.name];row[c.name]=v===undefined||v===''?c.nullable?null:'':/^(?:tinyint|smallint|mediumint|bigint|int|integer|decimal|numeric|float|double|real|number|boolean|bool|year)\b/i.test(c.type)?Number(v):v}setTables(prev=>({...prev,[table.name]:{...table,rows:[row,...table.rows]}}));setPending(true);setNewRowOpen(false);delete rowDrafts.current[table.name];rowForm.resetFields();setPage(1);message.success('已新增记录，点击“应用更改”保存')})}
