  <header className="titlebar"><div className="app-mark"><ProductLogo size={20}/></div><strong>风驰数据计算平台</strong><span className="titlebar-separator"/><span className="workspace-title">数据库工作区</span><div className="titlebar-right"><CloudServerOutlined/><span>Cloud workspace</span><span className="avatar">D</span></div></header>
